      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-usage-analytics\",\n  \"version\": \"0.2.1\",\n  \"description\": \"Local-first personal usage insights for DeepSeek Harness\",\n  \"type\": \"module\",\n  \"license\": \"MIT\",\n  \"author\": \"lawyer_cui\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/3361805598-gif/dsh-usage-analytics\"\n  },\n  \"homepage\": \"https://github.com/3361805598-gif/dsh-usage-analytics\",\n  \"bugs\": {\n    \"url\": \"https://github.com/3361805598-gif/dsh-usage-analytics/issues\"\n  },\n  \"main\": \"./lib/index.mjs\",\n  \"types\": \"./lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": { \"types\": \"./lib/types/index.d.ts\", \"import\": \"./lib/index.mjs\" },\n    \"./client\": \"./lib/client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\"lib/\", \"cordis.patch.yml\", \"README.md\", \"LICENSE\", \"CHANGELOG.md\"],\n  \"scripts\": {\n    \"build\": \"tsdown --config tsdown.config.ts && tsc -p tsconfig.build.json\",\n    \"preview:ui\": \"node scripts/preview.mjs\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"test\": \"vitest run\",\n    \"check\": \"npm run typecheck && npm test && npm run build\",\n    \"prepack\": \"npm run check\",\n    \"pack\": \"mkdir -p dist && npm pack --ignore-scripts --pack-destination dist\",\n    \"clean\": \"node -e \\\"const fs=require('fs'); for (const f of fs.readdirSync('.')) { if (f.endsWith('.tgz')) fs.unlinkSync(f) }\\\"\"\n  },\n  \"keywords\": [\"dsh\", \"dsh-plugin\", \"analytics\", \"token-usage\", \"local-first\", \"deepseek-harness\"],\n  \"engines\": { \"node\": \">=20\" },\n  \"dsh\": {\n    \"bundle\": { \"patch\": \"./cordis.patch.yml\" },\n    \"client\": {\n      \"inject\": [\"@deepseek-ai/dsh-client-runtime\", \"@deepseek-ai/dsh-client-ui-settings\"],\n      \"platform\": \"web\"\n    }\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-client-runtime\": \"0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-host-webserver\": \"0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-session\": \"0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-session-persistence\": \"0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-storage-domain\": \"0.1.1-rc.2\",\n    \"react\": \"^18.2.0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-client-runtime\": { \"optional\": true },\n    \"@deepseek-ai/dsh-client-ui-settings\": { \"optional\": true },\n    \"react\": { \"optional\": true }\n  },\n  \"dependencies\": { \"zod\": \"^4.3.6\" },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-client-runtime\": \"0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-host-webserver\": \"0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-session\": \"0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-session-persistence\": \"0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-storage-domain\": \"0.1.1-rc.2\",\n    \"@types/node\": \"^24.0.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"18.2.0\",\n    \"tsdown\": \"^0.22.2\",\n    \"typescript\": \"^5.6.0\",\n    \"vitest\": \"^4.1.8\"\n  }\n}\n"
