    {
      "path": "src/analytics/reducer.ts",
      "content": "import type { SessionEventLike, SessionHeaderLike, SessionUsageRecord, SkillFact, TokenBreakdown, UsageFact } from '../types.js'\n\nexport const REDUCER_VERSION = 2\n\nconst emptyTokens = (): TokenBreakdown => ({ input: 0, output: 0, cacheRead: 0, cacheWrite: 0, reasoning: 0, total: 0 })\n\nfunction numberOf(value: unknown): number {\n  return typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value : 0\n}\n\nfunction usageFrom(value: unknown): TokenBreakdown | undefined {\n  if (!value || typeof value !== 'object') return undefined\n  const raw = value as Record<string, unknown>\n  const seen = ['inputTokens', 'outputTokens', 'cacheReadTokens', 'cacheWriteTokens', 'reasoningTokens']\n    .some((key) => typeof raw[key] === 'number' && Number.isFinite(raw[key]) && raw[key] >= 0)\n  if (!seen) return undefined\n  const input = numberOf(raw.inputTokens)\n  const output = numberOf(raw.outputTokens)\n  const cacheRead = numberOf(raw.cacheReadTokens)\n  const cacheWrite = numberOf(raw.cacheWriteTokens)\n  const reasoning = numberOf(raw.reasoningTokens)\n  // reasoning is a subset of output in DSH TokenUsage, never add it twice.\n  return { input, output, cacheRead, cacheWrite, reasoning, total: input + output + cacheRead + cacheWrite }\n}\n\nfunction keyOf(data: Record<string, unknown>): string {\n  return `${String(data.turn ?? '')}:${String(data.step ?? '')}`\n}\n\nfunction providerAndModel(header: Record<string, unknown>): { provider: string; model: string } {\n  const config = header.config\n  if (!config || typeof config !== 'object') return { provider: 'unknown', model: 'unknown' }\n  const raw = config as Record<string, unknown>\n  return { provider: typeof raw.provider === 'string' ? raw.provider : 'unknown', model: typeof raw.model === 'string' ? raw.model : 'unknown' }\n}\n\nfunction isToolError(data: Record<string, unknown>): boolean {\n  if (data.error) return true\n  const message = data.message\n  if (!message || typeof message !== 'object') return false\n  const content = (message as Record<string, unknown>).content\n  return Array.isArray(content) && content.some((item) => Boolean(item && typeof item === 'object' && (item as Record<string, unknown>).isError))\n}\n\nfunction resultCallId(data: Record<string, unknown>): string | undefined {\n  const message = data.message\n  if (message && typeof message === 'object') {\n    const source = (message as Record<string, unknown>).source\n    if (source && typeof source === 'object' && typeof (source as Record<string, unknown>).callId === 'string') return (source as Record<string, string>).callId\n  }\n  return typeof data.callId === 'string' ? data.callId : undefined\n}\n\nfunction skillName(argumentsText: unknown): string {\n  if (typeof argumentsText !== 'string') return '未知技能'\n  try {\n    const parsed = JSON.parse(argumentsText) as unknown\n    const name = parsed && typeof parsed === 'object' ? (parsed as Record<string, unknown>).name : undefined\n    if (typeof name === 'string') return name\n  } catch { /* malformed arguments remain anonymous */ }\n  return '未知技能'\n}\n\n/** Reduce a durable session event stream into privacy-preserving facts. */\nexport function reduceSession(header: SessionHeaderLike, events: SessionEventLike[], revision: string | number, now = Date.now()): SessionUsageRecord {\n  const usage: UsageFact[] = []\n  const skills: SkillFact[] = []\n  const attempts = new Map<string, { usage?: TokenBreakdown; terminal: boolean; provider: string; model: string }>()\n  const pendingSkills = new Map<string, { name: string; at: number; turn: unknown }>()\n  let currentModel = { provider: 'unknown', model: 'unknown' }\n  const inheritedPrefix = header.seedLength ?? 0\n\n  for (const event of events) {\n    if (event.seq < inheritedPrefix || !event.data || typeof event.data !== 'object') continue\n    const data = event.data as Record<string, unknown>\n\n    if (event.type === 'request/header') {\n      const candidate = data.header\n      if (candidate && typeof candidate === 'object') currentModel = providerAndModel(candidate as Record<string, unknown>)\n      continue\n    }\n\n    if (event.type === 'assistant/chunk') {\n      const attempt = attempts.get(keyOf(data)) ?? { terminal: false, ...currentModel }\n      const chunk = data.chunk\n      if (chunk && typeof chunk === 'object') {\n        const raw = chunk as Record<string, unknown>\n        const reported = usageFrom(raw.usage)\n        if (reported) attempt.usage = reported\n        if (raw.finish && !attempt.terminal) {\n          attempt.terminal = true\n          const token = attempt.usage ?? emptyTokens()\n          usage.push({ at: event.time, provider: attempt.provider, model: attempt.model, known: Boolean(attempt.usage), ...token })\n        }\n      }\n      attempts.set(keyOf(data), attempt)\n      continue\n    }\n\n    if (event.type === 'assistant/message') {\n      const attempt = attempts.get(keyOf(data))\n      // A streamed terminal attempt is authoritative. The assembled message is its fallback only.\n      if (!attempt?.terminal) {\n        const message = data.message\n        const rawMessage = message && typeof message === 'object' ? message as Record<string, unknown> : {}\n        const reported = usageFrom(data.usage) ?? usageFrom(rawMessage.usage) ?? attempt?.usage\n        const token = reported ?? emptyTokens()\n        const source = rawMessage.source && typeof rawMessage.source === 'object' ? rawMessage.source as Record<string, unknown> : {}\n        usage.push({\n          at: event.time,\n          provider: typeof source.provider === 'string' ? source.provider : currentModel.provider,\n          model: typeof source.model === 'string' ? source.model : currentModel.model,\n          known: Boolean(reported),\n          ...token,\n        })\n      }\n      continue\n    }\n\n    if (event.type === 'tool/call' && data.name === 'skill') {\n      pendingSkills.set(String(data.callId ?? event.seq), { name: skillName(data.arguments), at: event.time, turn: data.turn })\n      continue\n    }\n\n    if (event.type === 'tool/result') {\n      const callId = resultCallId(data)\n      const call = callId === undefined ? undefined : pendingSkills.get(callId)\n      if (call) {\n        skills.push({ at: call.at, name: call.name, origin: 'automatic', status: isToolError(data) ? 'failure' : 'success', durationMs: Math.max(0, event.time - call.at) })\n        pendingSkills.delete(callId!)\n      }\n      continue\n    }\n\n    if (event.type === 'user/message') {\n      const message = data.message ?? data\n      const source = message && typeof message === 'object' ? (message as Record<string, unknown>).source : undefined\n      if (source && typeof source === 'object' && (source as Record<string, unknown>).kind === 'skill-invocation') {\n        const name = (source as Record<string, unknown>).name\n        skills.push({ at: event.time, name: typeof name === 'string' ? name : '未知技能', origin: 'explicit', status: 'success' })\n      }\n      continue\n    }\n\n    if (event.type === 'turn/end') {\n      for (const [callId, call] of pendingSkills) {\n        if (call.turn === data.turn) {\n          skills.push({ at: call.at, name: call.name, origin: 'automatic', status: 'incomplete' })\n          pendingSkills.delete(callId)\n        }\n      }\n    }\n  }\n\n  for (const call of pendingSkills.values()) skills.push({ at: call.at, name: call.name, origin: 'automatic', status: 'incomplete' })\n  const cutoff = now - 90 * 24 * 60 * 60 * 1000\n  return {\n    schemaVersion: 1, reducerVersion: REDUCER_VERSION, sessionId: header.id, sourceCreatedAt: header.createdAt, sourceRevision: revision,\n    ...(header.parentSession ? { parentSession: header.parentSession } : {}),\n    origin: header.origin === 'subagent' ? 'subagent' : 'root', updatedAt: now,\n    usage: usage.filter((item) => item.at >= cutoff), skills: skills.filter((item) => item.at >= cutoff),\n  }\n}\n\nexport function addTokens(target: TokenBreakdown, source: TokenBreakdown): void {\n  target.input += source.input; target.output += source.output; target.cacheRead += source.cacheRead\n  target.cacheWrite += source.cacheWrite; target.reasoning += source.reasoning; target.total += source.total\n}\n\nexport { emptyTokens }\n"
    },
    {
      "path": "src/analytics/indexer.ts",
      "content": "import type { Context } from '@deepseek-ai/cordis'\nimport type { KvTable } from '@deepseek-ai/dsh-storage-domain'\nimport { REDUCER_VERSION, reduceSession } from './reducer.js'\nimport { buildSummary } from './summary.js'\nimport { usageInsightsDomain } from './spec.js'\nimport type { SessionEventLike, SessionHeaderLike, SessionUsageRecord, UsageRange, UsageSummaryV1 } from '../types.js'\n\ntype Snapshot = { header: SessionHeaderLike; revision: string | number }\ntype LiveSession = { id: string; header: SessionHeaderLike; events: SessionEventLike[] }\ntype HostContext = Context & {\n  sessionPersistence: { listSnapshots(): Promise<Snapshot[]>; readFrom(id: string, fromSeq: number): Promise<{ meta: SessionHeaderLike; events: SessionEventLike[] }> }\n  sessions: { flush(session: LiveSession): Promise<void>; get(id: string): LiveSession | undefined }\n  storageDomain: Context['storageDomain']\n}\n\nexport class UsageInsightsIndex {\n  private table!: KvTable<string, SessionUsageRecord>\n  private records = new Map<string, SessionUsageRecord>()\n  private index: UsageSummaryV1['index'] = { state: 'indexing', processedSessions: 0, totalSessions: 0, failures: 0 }\n  private domainClose?: () => Promise<void>\n  private queue: Promise<void> = Promise.resolve()\n  private refreshPending: Promise<void> | undefined\n  private rebuildPending: Promise<void> | undefined\n  private disposed = false\n\n  constructor(private readonly ctx: HostContext) {}\n\n  async start(): Promise<void> {\n    const domain = await this.ctx.storageDomain.open(usageInsightsDomain)\n    this.domainClose = () => domain.close()\n    this.ctx.effect(() => async () => {\n      this.disposed = true\n      await this.queue\n      await this.domainClose?.()\n    }, 'usageInsights.domainClose')\n    this.table = domain.table('sessions')\n    this.records = new Map(this.table.entries())\n    await this.prune()\n    this.installLiveReducer()\n    void this.refresh()\n    this.ctx.effect(() => {\n      const timer = setInterval(() => void this.refresh(), 60_000)\n      timer.unref()\n      return () => clearInterval(timer)\n    }, 'usageInsights.refresh')\n  }\n\n  summary(range: UsageRange, timeZone: string): UsageSummaryV1 {\n    return buildSummary(this.records.values(), { range, timeZone, index: this.index, unreadableSessions: this.index.failures })\n  }\n\n  rebuild(): Promise<void> {\n    if (this.rebuildPending) return this.rebuildPending\n    this.index = { state: 'indexing', processedSessions: 0, totalSessions: this.records.size, failures: 0 }\n    this.rebuildPending = this.enqueue(async () => {\n      for (const key of [...this.table.keys()]) {\n        await this.table.delete(key)\n        this.records.delete(key)\n      }\n      await this.backfill()\n    }).finally(() => { this.rebuildPending = undefined })\n    return this.rebuildPending\n  }\n\n  private enqueue(operation: () => Promise<void>): Promise<void> {\n    this.queue = this.queue.then(async () => {\n      if (this.disposed) return\n      try { await operation() } catch { this.index.state = 'error' }\n    })\n    return this.queue\n  }\n\n  private refresh(): Promise<void> {\n    if (this.refreshPending) return this.refreshPending\n    this.refreshPending = this.enqueue(() => this.backfill())\n      .finally(() => { this.refreshPending = undefined })\n    return this.refreshPending\n  }\n\n  private async prune(): Promise<void> {\n    const cutoff = Date.now() - 90 * 24 * 60 * 60 * 1000\n    for (const record of this.records.values()) {\n      const usage = record.usage.filter((item) => item.at >= cutoff)\n      const skills = record.skills.filter((item) => item.at >= cutoff)\n      if (usage.length !== record.usage.length || skills.length !== record.skills.length) {\n        await this.save({ ...record, usage, skills })\n      }\n    }\n  }\n\n  private installLiveReducer(): void {\n    const events = this.ctx as unknown as { on(name: string, listener: (session: LiveSession, event: SessionEventLike) => void): void }\n    events.on('session/event', (session, event) => {\n      // A turn boundary is both stable and cheap: flush source events first, then replace the whole fact record.\n      if (event.type === 'turn/end') void this.enqueue(() => this.syncLive(session))\n    })\n  }\n\n  private async syncLive(session: LiveSession): Promise<void> {\n    try {\n      await this.ctx.sessions.flush(session)\n      const snapshots = await this.ctx.sessionPersistence.listSnapshots()\n      const snapshot = snapshots.find((item) => item.header.id === session.id)\n      if (!snapshot) return\n      // Read durable events: the live array may already contain the next, unflushed turn.\n      const source = await this.ctx.sessionPersistence.readFrom(session.id, 0)\n      const record = reduceSession(source.meta, source.events, String(snapshot.revision))\n      await this.save(record)\n    } catch {\n      // The periodic reconciliation retries failures without publishing live-only facts.\n      this.index.state = 'partial'\n    }\n  }\n\n  private async backfill(): Promise<void> {\n    try {\n      await this.prune()\n      const snapshots = await this.ctx.sessionPersistence.listSnapshots()\n      const available = new Set(snapshots.map((item) => item.header.id))\n      this.index = { state: 'indexing', processedSessions: 0, totalSessions: snapshots.length, failures: 0 }\n      for (const key of [...this.records.keys()]) {\n        if (!available.has(key)) { await this.table.delete(key); this.records.delete(key) }\n      }\n      for (const snapshot of snapshots) {\n        const existing = this.records.get(snapshot.header.id)\n        const revision = String(snapshot.revision)\n        if (existing?.reducerVersion === REDUCER_VERSION && existing.sourceCreatedAt === snapshot.header.createdAt && String(existing.sourceRevision) === revision) {\n          this.index.processedSessions += 1\n          continue\n        }\n        try {\n          const source = await this.ctx.sessionPersistence.readFrom(snapshot.header.id, 0)\n          await this.save(reduceSession(source.meta, source.events, revision))\n        } catch {\n          this.index.failures += 1\n        } finally {\n          this.index.processedSessions += 1\n        }\n      }\n      this.index.state = this.index.failures ? 'partial' : 'ready'\n    } catch {\n      this.index.state = 'error'\n    }\n  }\n\n  private async save(record: SessionUsageRecord): Promise<void> {\n    await this.table.put(record.sessionId, record)\n    this.records.set(record.sessionId, record)\n  }\n}\n"
